'use strict';
const el=id=>document.getElementById(id);let teacherKey='';try{teacherKey=sessionStorage.getItem('volldampf-teacher')||''}catch{}
let selected='',snapshot=null,timer=null,loading=false;
const element=(tag,text,className)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node};
function message(text,error=false){el('message').textContent=text;el('message').className=error?'error':''}
async function request(path,method='GET',data){const res=await fetch(window.QUIZ_API+path,{method,headers:{Authorization:`Bearer ${teacherKey}`,...(data?{'Content-Type':'application/json'}:{})},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(15000)});const json=await res.json();if(!res.ok)throw new Error(json.error||'Verbindung fehlgeschlagen.');return json}
async function classes(){const data=await request('/teacher/classes');el('class-select').replaceChildren(element('option','Klasse auswählen'));el('class-select').firstChild.value='';data.classes.forEach(room=>{const option=element('option',`${room.label} · ${room.participants} Versuche${room.closed?' · gesperrt':''}`);option.value=room.code;el('class-select').append(option)});if(data.classes.some(x=>x.code===selected))el('class-select').value=selected;el('empty').hidden=data.classes.length>0;return data}
async function login(){await classes();el('login').hidden=true;el('dashboard').hidden=false;el('logout').hidden=false;try{sessionStorage.setItem('volldampf-teacher',teacherKey)}catch{}message('Wähle eine Klasse oder lege eine neue Durchführung an.');clearInterval(timer);timer=setInterval(()=>{if(selected&&!document.hidden)void refresh()},10000)}
el('login').onsubmit=async e=>{e.preventDefault();teacherKey=el('teacher-key').value.trim();const b=e.submitter;b.disabled=true;try{await login();el('teacher-key').value=''}catch(error){teacherKey='';message(error.message,true)}finally{b.disabled=false}};
el('logout').onclick=()=>{clearInterval(timer);teacherKey='';selected='';snapshot=null;try{sessionStorage.removeItem('volldampf-teacher')}catch{}el('dashboard').hidden=true;el('class-view').hidden=true;el('login').hidden=false;el('logout').hidden=true;el('answer-table').replaceChildren();el('individuals').replaceChildren();message('Abgemeldet.')};
el('create-class').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const room=await request('/teacher/classes','POST',{label:el('class-name').value.trim()});selected=room.code;await classes();await refresh();el('class-name').value='';message('Klasse angelegt. Teile den Teilnahmelink oder den Klassencode.')}catch(error){message(error.message,true)}finally{button.disabled=false}};
el('class-select').onchange=()=>{selected=el('class-select').value;snapshot=null;el('class-view').hidden=true;if(selected)void refresh()};
async function refresh(){if(!selected||loading)return;loading=true;const code=selected;el('refresh').disabled=true;try{const data=await request(`/teacher/classes/${code}`);if(selected!==code)return;snapshot=data;render(data);message('')}catch(error){message(`Aktualisierung fehlgeschlagen: ${error.message} Die angezeigten Daten können veraltet sein.`,true)}finally{loading=false;el('refresh').disabled=false;if(selected&&code!==selected)void refresh()}}
function render({room,attempts}){el('class-view').hidden=false;el('class-title').textContent=room.label;el('room-code').textContent=room.code;const link=new URL('./',location.href);link.searchParams.set('klasse',room.code);el('join-link').value=link.href;el('toggle-class').textContent=room.closed?'Neue Teilnahmen wieder erlauben':'Neue Teilnahmen sperren';el('stat-attempts').textContent=attempts.length;const complete=attempts.filter(a=>a.complete);el('stat-complete').textContent=complete.length;el('stat-average').textContent=complete.length?`${(complete.reduce((sum,a)=>sum+a.score,0)/complete.length).toFixed(1)} / 8`:'–';el('updated').textContent=`Stand: ${new Date().toLocaleTimeString('de-CH')}`;
 const analysis=el('question-analysis');analysis.replaceChildren();questions.forEach((q,i)=>{const counts=[0,0,0,0];attempts.forEach(a=>{const answer=a.answers.find(x=>x.question===i);if(answer)counts[answer.choice]++});const total=counts.reduce((a,b)=>a+b,0);const correct=counts[q.correct];const item=element('article',undefined,'analysis-item');item.append(element('h3',`${i+1}. ${q.q}`),element('p',total?`${Math.round(correct/total*100)} % richtig · ${total} Antworten · ${attempts.length-total} offen`:'Noch keine Antworten'));const progress=element('progress');progress.max=total||1;progress.value=correct;progress.setAttribute('aria-label',`Frage ${i+1}: ${correct} von ${total} richtig`);item.append(progress);const dist=element('div',undefined,'distribution');counts.forEach((count,j)=>{const cell=element('span',`${'ABCD'[j]}${j===q.correct?' ✓':''}: ${count}`,j===q.correct?'solution':'');cell.title=q.answers[j];dist.append(cell)});item.append(dist);const details=element('details');details.append(element('summary','Antwortmöglichkeiten anzeigen'));const list=element('ol');list.type='A';q.answers.forEach((a,j)=>list.append(element('li',a+(j===q.correct?' ✓':''))));details.append(list);item.append(details);analysis.append(item)});
 const table=element('table');const head=element('thead');const tr=element('tr');['Kürzel','Status',...questions.map((_,i)=>`F${i+1}`),'Punkte'].forEach(label=>tr.append(element('th',label)));head.append(tr);table.append(head);const tbody=element('tbody');const individuals=el('individuals');individuals.replaceChildren();attempts.forEach((attempt,n)=>{const row=element('tr');row.append(element('td',attempt.alias),element('td',attempt.complete?'Fertig':`${attempt.answers.length}/8`));questions.forEach((q,i)=>{const a=attempt.answers.find(x=>x.question===i);const cell=element('td',a?`${'ABCD'[a.choice]} ${a.choice===q.correct?'✓':'✕'}`:'–',a?(a.choice===q.correct?'right':'wrong'):'');cell.title=a?q.answers[a.choice]:'Noch offen';row.append(cell)});row.append(element('td',`${attempt.score} / 8`));tbody.append(row);const details=element('details');details.append(element('summary',`${attempt.alias} · Versuch ${n+1} · ${attempt.score}/8 · ${new Date(attempt.created_at).toLocaleString('de-CH')}`));const list=element('ol');questions.forEach((q,i)=>{const a=attempt.answers.find(x=>x.question===i);const li=element('li');li.append(element('strong',q.q),element('div',a?`Antwort: ${q.answers[a.choice]}`:'Noch nicht beantwortet'),element('div',`Lösung: ${q.answers[q.correct]}`));list.append(li)});details.append(list);individuals.append(details)});table.append(tbody);el('answer-table').replaceChildren(attempts.length?table:element('p','Noch keine Teilnahmen. Teile den Link mit deiner Klasse.'));el('export').disabled=attempts.length===0;
}
el('refresh').onclick=()=>void refresh();el('copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(el('join-link').value);message('Teilnahmelink kopiert.')}catch{el('join-link').select();message('Bitte den markierten Link kopieren.')}};
el('toggle-class').onclick=async()=>{if(!snapshot)return;try{await request(`/teacher/classes/${selected}`,'PATCH',{closed:!snapshot.room.closed});await classes();await refresh()}catch(e){message(e.message,true)}};
el('delete-class').onclick=async()=>{if(!snapshot||!confirm(`«${snapshot.room.label}» mit sämtlichen Antworten endgültig löschen?`))return;try{await request(`/teacher/classes/${selected}`,'DELETE');selected='';snapshot=null;el('class-view').hidden=true;await classes();message('Klasse und Antworten gelöscht.')}catch(e){message(e.message,true)}};
function csvCell(value){let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
el('export').onclick=()=>{if(!snapshot)return;const rows=[['Klasse','Klassencode','Versuch-ID','Kürzel','Gestartet','Status','Punkte','Frage','Fragetext','Antwortbuchstabe','Antworttext','Richtig','Antwortzeit']];snapshot.attempts.forEach(a=>questions.forEach((q,i)=>{const r=a.answers.find(x=>x.question===i);rows.push([snapshot.room.label,snapshot.room.code,a.id,a.alias,a.created_at,a.complete?'Abgeschlossen':'Laufend',a.score,i+1,q.q,r?'ABCD'[r.choice]:'',r?q.answers[r.choice]:'',r?(r.choice===q.correct?'Ja':'Nein'):'Offen',r?.answered_at||''])}));const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=element('a');a.href=url;a.download=`volldampf-${snapshot.room.code}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
if(teacherKey)void login().catch(e=>{teacherKey='';try{sessionStorage.removeItem('volldampf-teacher')}catch{}message(e.message,true)});
